import{_ as d,C as r,o,c as h,aj as e,E as n}from"./framework.js";const _=JSON.parse('{"title":"控制台：余额 | Product / Console | Documentation","description":"控制台：余额 in Kooboo: 余额属于当前组织。切换组织后，余额、最近收支和订单都会变成另一个组织的数据。","frontmatter":{"title":"控制台：余额 | Product / Console | Documentation","description":"控制台：余额 in Kooboo: 余额属于当前组织。切换组织后，余额、最近收支和订单都会变成另一个组织的数据。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/balance.html"}]]},"headers":[],"relativePath":"zh/product/console/balance.md","filePath":"product/console/balance.md","lastUpdated":1781010536000}'),l={name:"zh/product/console/balance.md"};function c(i,t,s,b,p,m){const a=r("DocImage");return o(),h("div",null,[t[0]||(t[0]=e('<h1 id="控制台-余额" tabindex="-1">控制台：余额 <a class="header-anchor" href="#控制台-余额" aria-label="Permalink to &quot;控制台：余额&quot;">​</a></h1><blockquote><p>查看当前组织余额、最近收支记录，并从余额页发起充值订单。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>余额</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/balance</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/balance</code></td></tr><tr><td>可见身份</td><td>组织管理员</td></tr></tbody></table><p>余额属于当前组织。切换组织后，余额、最近收支和订单都会变成另一个组织的数据。</p>',5)),n(a,{src:"/product/console/balance-overview.png",alt:"控制台余额与最近收支记录（金额已脱敏）",width:"1120"}),t[1]||(t[1]=e('<h2 id="当前余额" tabindex="-1">当前余额 <a class="header-anchor" href="#当前余额" aria-label="Permalink to &quot;当前余额&quot;">​</a></h2><p>余额页表格顶部显示：</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>Current Balance</td><td>当前余额金额</td></tr><tr><td>Currency</td><td>余额币种</td></tr><tr><td>Recharge</td><td>打开充值弹窗</td></tr></tbody></table><p>如果你准备购买域名、续费会员或使用在线 AI 能力，建议先在这里确认余额。</p><h2 id="最近收支记录" tabindex="-1">最近收支记录 <a class="header-anchor" href="#最近收支记录" aria-label="Permalink to &quot;最近收支记录&quot;">​</a></h2><p>表格显示最近收支：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Name</td><td>收支项目名称</td></tr><tr><td>Date</td><td>发生时间</td></tr><tr><td>Direction</td><td>加款或扣费方向</td></tr><tr><td>Amount</td><td>金额</td></tr></tbody></table><p><code>Direction</code> 使用图标区分收入与支出。排查扣费时，优先按日期和金额定位记录，再到 <a href="./orders.html">订单</a> 页核对订单状态。</p><h2 id="充值" tabindex="-1">充值 <a class="header-anchor" href="#充值" aria-label="Permalink to &quot;充值&quot;">​</a></h2><p>点击 <code>Recharge</code> 会打开充值弹窗。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Amount</td><td>充值金额，默认填入 <code>50</code></td></tr><tr><td>Currency</td><td>当前余额币种，只读展示</td></tr><tr><td>Recharge</td><td>校验金额后创建充值订单</td></tr></tbody></table><p>确认充值后会跳转到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/checkOrder?orderId={orderId}</span></span></code></pre></div><p>后续在 <a href="./orders.html#结账页">订单：结账页</a> 选择信用卡或微信支付。</p><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>充值账户</td><td>余额 -&gt; Recharge -&gt; 填金额 -&gt; 结账页付款</td></tr><tr><td>核对扣费</td><td>余额 -&gt; 最近收支记录 -&gt; 订单页核对对应订单</td></tr><tr><td>AI 使用前准备</td><td>余额 -&gt; <a href="./ai-config.html">AI 配置</a> -&gt; <a href="/kb-docs/zh/cms/settings/ai-service.html">CMS：AI 服务</a></td></tr><tr><td>域名购买前准备</td><td>余额 -&gt; <a href="./domains.html#购买域名">域名</a></td></tr></tbody></table><h2 id="与充值面板的关系" tabindex="-1">与充值面板的关系 <a class="header-anchor" href="#与充值面板的关系" aria-label="Permalink to &quot;与充值面板的关系&quot;">​</a></h2><p>顶部导航的充值图标是快捷面板，余额页是完整页面：</p><table tabindex="0"><thead><tr><th>顶部充值面板</th><th>余额页</th></tr></thead><tbody><tr><td>快速查看余额、域名到期和会员到期</td><td>查看当前余额和最近收支记录</td></tr><tr><td>适合临时充值或续费提醒</td><td>适合账务核对</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./orders.html">订单</a></td><td>充值后的支付和订单状态</td></tr><tr><td><a href="./renewals.html">续费</a></td><td>查看到期续费项</td></tr></tbody></table>',21))])}const g=d(l,[["render",c]]);export{_ as __pageData,g as default};
